const m = $input.first().json || {};
if (m.error) return [{ json: { error: 'could_not_read_message' } }];
function addr(a){ if (!a) return ''; if (typeof a === 'string') return a; if (a.text) return a.text; if (Array.isArray(a.value)) return a.value.map(function(v){ return (v.name ? v.name + ' ' : '') + '<' + v.address + '>'; }).join(', '); return ''; }
let body = m.text || '';
if (!body && m.html) { body = String(m.html).replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|tr|li|h[1-6])>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'").replace(/&quot;/g, '"'); }
body = body.replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n\n').trim();
const MAX = 4000;
const truncated = body.length > MAX;
if (truncated) body = body.slice(0, MAX);
const attachments = Object.keys(m.binary || {}).length || (Array.isArray(m.attachments) ? m.attachments.length : 0);
return [{ json: { id: m.id, threadId: m.threadId, from: addr(m.from), to: addr(m.to), date: m.date || '', subject: m.subject || '', body: body, truncated: truncated, attachments: attachments } }];

